 private final android.os.Handler widgetHandler=new android.os.Handler(android.os.Looper.getMainLooper());private final Runnable widgetTick=new Runnable(){public void run(){WidgetSync.capture(MainActivity.this);widgetHandler.postDelayed(this,60000);}};
